    for index in np.flatnonzero(np.abs(derivative) > threshold):
        boundary = int(index + 1)
        if boundary < 18 or n - boundary < 18:
            continue
        if not boundaries or boundary - boundaries[-1] >= 18:
            boundaries.append(boundary)
    boundaries = boundaries[:4]
    edges = [0] + boundaries + [n]

    def local_period(segment):
        """Estimate the dominant period from robust local autocorrelation."""
        z = np.asarray(segment, dtype=float)
        length = len(z)
        if length < 16:
            return max(6.0, length / 3.0)
        z = z - np.median(z)
        energy = float(np.dot(z, z))
        if not np.isfinite(energy) or energy <= 1e-12:
            return max(6.0, length / 3.0)

        maximum = min(length // 2, 48)
        if maximum < 3:
            return max(6.0, length / 3.0)

        correlations = np.asarray([
            float(np.dot(z[:-lag], z[lag:])) / energy
            for lag in range(3, maximum + 1)
        ], dtype=float)
        if correlations.size == 0:
            return max(6.0, length / 3.0)

        lag = int(np.argmax(correlations)) + 3
        return float(np.clip(lag, 6.0, max(8.0, length / 2.0)))

    def posterior(segment, kind):
        """Compute one GP posterior mean using at most 96 inducing knots."""
        segment = np.asarray(segment, dtype=float)
        length = len(segment)
        if length < 8:
            return _savgol_safe(segment, 7)

        knot_count = min(96, length)
        knot_indices = np.unique(
            np.linspace(0, length - 1, knot_count).astype(int)
        )
        scale = float(max(length - 1, 1))
        knots = knot_indices.astype(float) / scale
        query = np.arange(length, dtype=float) / scale

        distance = np.abs(knots[:, None] - knots[None, :])
        query_distance = np.abs(query[:, None] - knots[None, :])
        period = local_period(segment) / scale

        short_scale = 0.060
        long_scale = 0.25

        short = np.exp(-distance / short_scale) * (
            1.0 + distance / short_scale
        )
        long = np.exp(-distance / long_scale) * (
            1.0 + distance / long_scale
        )
        periodic = np.exp(
            -2.0 * np.sin(
                np.pi * distance / max(period, 1e-3)
            ) ** 2 / 0.20 ** 2
        ) * np.exp(-distance / 0.45)

        short_cross = np.exp(-query_distance / short_scale) * (
            1.0 + query_distance / short_scale
        )
        long_cross = np.exp(-query_distance / long_scale) * (
            1.0 + query_distance / long_scale
        )
        periodic_cross = np.exp(
            -2.0 * np.sin(
                np.pi * query_distance / max(period, 1e-3)
            ) ** 2 / 0.20 ** 2
        ) * np.exp(-query_distance / 0.45)

        if kind == 0:
            covariance, cross = short, short_cross
        elif kind == 1:
            covariance, cross = long, long_cross
        elif kind == 2:
            covariance, cross = periodic, periodic_cross
        else:
            covariance = 0.68 * long + 0.32 * short
            cross = 0.68 * long_cross + 0.32 * short_cross

        covariance = np.asarray(covariance, dtype=float).copy()
        covariance.flat[::len(covariance) + 1] += noise_var

        values = segment[knot_indices]
        try:
            chol = np.linalg.cholesky(covariance)
            coefficients = np.linalg.solve(
                chol.T,
                np.linalg.solve(chol, values),
            )
            result = cross @ coefficients
        except np.linalg.LinAlgError:
            # One bounded jitter retry avoids invalid output without
            # introducing an iterative optimizer.
            covariance.flat[::len(covariance) + 1] += 1e-5
            try:
                coefficients = np.linalg.solve(covariance, values)
                result = cross @ coefficients
            except Exception:
                return _savgol_safe(segment, 7)
        except Exception:
            return _savgol_safe(segment, 7)

        return np.where(np.isfinite(result), result, _savgol_safe(segment, 7))

    output = np.empty(n, dtype=float)

    for start, stop in zip(edges[:-1], edges[1:]):
        segment = np.asarray(x[start:stop], dtype=float)
        length = len(segment)

        if length < 10:
            output[start:stop] = _savgol_safe(segment, 7)
            continue

        candidates = [
            posterior(segment, kind)
            for kind in range(4)
        ]

        # Robust model selection favors trend fidelity but penalizes
        # curvature and noise-induced hysteretic reversals.
        local_scale = max(_mad_sigma(np.diff(segment)), 1e-8)
        signal_scale = max(_mad_sigma(segment), local_scale, 1e-8)
        scores = []

        for candidate in candidates:
            residual = candidate - segment
            residual_cost = _mad_sigma(residual) / local_scale
            curvature_cost = (
                _mad_sigma(np.diff(candidate, n=2)) / signal_scale
                if length > 2 else 0.0
            )
            excursion = max(1.35 * local_scale, 1e-8)
            reversals = max(
                len(_hysteretic_extrema(candidate, excursion)) - 2,
                0,
            )
            scores.append(
                residual_cost
                + 0.16 * curvature_cost
                + 0.24 * reversals / max(length, 1)
            )

        selected = np.asarray(
            candidates[int(np.argmin(scores))],
            dtype=float,
        )

        # Limit endpoint artifacts from the inducing-point reconstruction
        # while retaining the selected kernel's interior dynamics.
        local = _savgol_safe(segment, 7)
        edge_length = min(5, length // 3)
        if edge_length:
            gain = np.ones(length, dtype=float)
            ramp = np.linspace(0.55, 1.0, edge_length)
            gain[:edge_length] = ramp
            gain[-edge_length:] = ramp[::-1]
            selected = local + gain * (selected - local)

        output[start:stop] = selected

    return np.where(
        np.isfinite(output),
        output,
        _adaptive_full_record_filter(x),
    )


def adaptive_filter(x, window_size=20):
    """Apply change-point-aware GP kernel-bank denoising with aligned output."""
    x = _finite_signal(x)
    if len(x) < window_size:
        raise ValueError(
            f"Input signal length ({len(x)}) must be >= window_size ({window_size})"
        )
    return _gp_kernel_bank_filter(x)[window_size - 1:]
